{
  "concepts": [
    {
      "conditions": [],
      "definition": "F15 addresses release identification, publication, qualification, acceptance, selection and successor conservation. Its instance premises are recursive products, published cuts, mutable carriers, derived assets, external services and successor lines; these premises are additional to the commitments.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 110,
          "quote": "Its instance premises, which the commitments do not supply, are\nnamed in the rows as follows:",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F1.%20Context%20and%20position%2FFoundation%20to%20law%3A%20release%20and%20successor%20conservation",
          "start_line": 100
        }
      ],
      "key": "release_conservation_family",
      "label": "Release and successor conservation family"
    },
    {
      "conditions": [],
      "definition": "Substrate, development product, source project, release cut, product, install, artifact and product definition are distinct lineage roles. Each binds its own identity and basis. Candidate source, release cut, release subject and version-line selector are also distinct generic release objects.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 118,
          "quote": "substrate, development product, source project, release cut, product, install, artifact and product definition are distinct objects.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F1.%20Context%20and%20position%2FFoundation%20to%20law%3A%20release%20and%20successor%20conservation",
          "start_line": 118
        },
        {
          "end_line": 119,
          "quote": "a candidate source, a release cut, a release subject and a version-line selector are distinct, and equal version text collapses none.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F1.%20Context%20and%20position%2FFoundation%20to%20law%3A%20release%20and%20successor%20conservation",
          "start_line": 119
        }
      ],
      "key": "lineage_objects",
      "label": "Product lineage and generic release objects"
    },
    {
      "conditions": [],
      "definition": "A stable repository-local key assigned by Product release authority to one independently released source project.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 164,
          "quote": "- Project Release Namespace: a stable repository-local key assigned by\n  the Product release authority to one independently released source\n  project;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 162
        }
      ],
      "key": "project_release_namespace",
      "label": "Project Release Namespace"
    },
    {
      "conditions": [],
      "definition": "The exact repository-relative source-project root and Git tree object selected for one cut.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 166,
          "quote": "- Project Subtree: the exact repository-relative source-project root and\n  Git tree object selected for one cut;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 165
        }
      ],
      "key": "project_subtree",
      "label": "Project Subtree"
    },
    {
      "conditions": [],
      "definition": "Mutable source-project state constructing a possible successor.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 168,
          "quote": "- Candidate Source: the candidate source of FOUNDATIONS §2, the mutable\n  source-project state constructing a possible successor;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 167
        }
      ],
      "key": "candidate_source",
      "label": "Candidate Source"
    },
    {
      "conditions": [],
      "definition": "Mutable project-qualified carrier for the current candidate window.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 170,
          "quote": "- RC Branch: a mutable project-qualified carrier for the current\n  candidate window;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 169
        }
      ],
      "key": "rc_branch",
      "label": "RC Branch"
    },
    {
      "conditions": [],
      "definition": "An annotated project-qualified Git tag together with its exact Product release subject, naming one published candidate and, once accepted, one released Product; it realises a release cut.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 173,
          "quote": "- Immutable RC Cut: an annotated project-qualified Git tag plus its exact\n  Product release subject (FOUNDATIONS §2), naming one published candidate\n  and, once accepted, one released Product; it realises the release cut;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 171
        }
      ],
      "key": "immutable_rc_cut",
      "label": "Immutable RC Cut"
    },
    {
      "conditions": [],
      "definition": "Mutable project-qualified tag alias naming the highest-ordinal published immutable RC cut for one project and version line; a discovery selector rather than a consumer's governing basis.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 176,
          "quote": "- Version-Line Selector: the mutable project-qualified tag alias naming\n  the highest-ordinal published immutable RC cut for that project and\n  version line; it realises the version-line selector of FOUNDATIONS §2;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 174
        }
      ],
      "key": "version_line_selector",
      "label": "Version-Line Selector"
    },
    {
      "conditions": [],
      "definition": "Optional mutable project-qualified convenience carrier aligned with the selector's latest-published commit.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 179,
          "quote": "- Release Branch: an optional mutable project-qualified convenience\n  carrier aligned to the same latest-published commit as the selector.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F2.%20Release%20identities",
          "start_line": 178
        }
      ],
      "key": "release_branch",
      "label": "Release Branch"
    },
    {
      "conditions": [],
      "definition": "Three-phase process: mutable candidate construction; immutable RC publication with monotonic version-line advancement; exact-cut qualification, acceptance and explicit consumer adoption.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 279,
          "quote": "1. mutable candidate construction;\n2. immutable RC publication and monotonic version-line advancement; and\n3. exact-cut qualification, acceptance and explicit consumer adoption.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F3.%20Phases",
          "start_line": 277
        }
      ],
      "key": "release_process",
      "label": "Release process"
    },
    {
      "conditions": [],
      "definition": "Evaluation bound to an exact immutable cut, its release claims, governing basis, observation boundaries, evidence, owner verdicts, gaps and complete predecessor-successor relation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 347,
          "quote": "- the exact release-scoped claim bytes;\n- the governing Product and release basis;\n- each claimed property and its observation boundary;\n- evidence subjects, owner verdicts and unresolved gaps; and\n- the complete successor relation to the declared predecessor (§9).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F3.%20Phases%2FExact-cut%20qualification",
          "start_line": 343
        }
      ],
      "key": "exact_cut_qualification",
      "label": "Exact-cut qualification"
    },
    {
      "conditions": [],
      "definition": "Separate explicit Product-Definition transition that resolves, presents, installs, verifies and pins a selected immutable RC. Its read-only Adoption Plan binds the current definition bytes and basis to exact target identities and emits a deterministic digest; fleet adoption uses one aggregate digest over all exact per-definition plans.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 409,
          "quote": "Adoption is a separate\nexplicit Product-Definition transition that resolves, presents, installs,\nverifies and pins the selected immutable RC.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F4.%20Selector%20and%20consumer%20adoption",
          "start_line": 407
        },
        {
          "end_line": 429,
          "quote": "The read-only plan,\nthe Adoption Plan of PRODUCT_DEFINITION §4, binds the current Product\nDefinition bytes and basis to the target immutable cut, annotated tag\nobject, peeled commit, tree and installed-manifest digest, then emits a\ndeterministic plan digest.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F4.%20Selector%20and%20consumer%20adoption",
          "start_line": 425
        }
      ],
      "key": "consumer_adoption",
      "label": "Consumer adoption and Adoption Plan"
    },
    {
      "conditions": [],
      "definition": "Optional release-scoped surfaces include release notes, release and installed-distribution manifests, dependency declarations, package or installed-carrier metadata, qualification receipts, and branch and tag identity declarations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 477,
          "quote": "- release notes;\n- release and installed-distribution manifests;\n- dependency declarations;\n- package or installed-carrier metadata;\n- qualification receipts; and\n- branch and tag identity declarations.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F6.%20Release-scoped%20assets%20and%20the%20Product%20subject%2FRelease-scoped%20assets",
          "start_line": 472
        }
      ],
      "key": "release_scoped_assets",
      "label": "Release-scoped assets"
    },
    {
      "conditions": [],
      "definition": "Declared exact Product member set or artifact constituting the release subject, distinguished from its describing claim surfaces, excluded mutable source fields and the wider repository carrier.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 499,
          "quote": "- the exact Product member set or artifact constituting the release\n  subject;\n- the release-scoped claim surfaces describing that subject; and\n- co-located mutable source-project fields excluded from both.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F6.%20Release-scoped%20assets%20and%20the%20Product%20subject%2FProduct%20subject%20and%20repository%20carrier",
          "start_line": 496
        }
      ],
      "key": "product_release_subject",
      "label": "Product release subject"
    },
    {
      "conditions": [
        "A Product authority explicitly declares the relation when a source corpus and required distributed or derived assets need to remain usable as one versioned set."
      ],
      "definition": "Cross-Product Release-Matched Asset Cohort naming every required Product and asset, exact source dependency, owning authorities, qualification boundary and publication transaction. The closed STDO stack cohort contains the standards corpus cut; distributed spec plugin and host assets carried by it; exact Axiom Indexer mechanics Product; exact STDO Representation Product; and its released a_c.STDO program and logical constraint map or equivalent semantic index, with complete source inventory, member digests, member-set digest and derivation cut identity.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 518,
          "quote": "A Product authority may declare an explicit cross-Product Release-Matched\nAsset Cohort when one source corpus and its required distributed or\nderived assets need to remain usable as one versioned set.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F7.%20Coordinated%20release-matched%20asset%20cohorts",
          "start_line": 511
        },
        {
          "end_line": 539,
          "quote": "5. its released `a_c.STDO` axiomatic program and logical constraint map\n   or equivalent semantic index, with the complete source-STDO member\n   inventory, member digests, member-set digest and exact cut identity\n   used to derive it.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F7.%20Coordinated%20release-matched%20asset%20cohorts",
          "start_line": 536
        }
      ],
      "key": "release_matched_cohort",
      "label": "Release-Matched Asset Cohort"
    },
    {
      "conditions": [
        "Coordinated STDO cohort publication."
      ],
      "definition": "Bounded construction using commit A for the exact STDO source cut and commit B for derived Products and index, followed by one atomic publication transaction. The separation avoids a same-commit self-reference because installed-manifest identity includes the annotated STDO tag object.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 556,
          "quote": "Exact installed-manifest identity includes the annotated STDO tag object,\nso a same-commit carrier containing both that identity and derived child\nbytes would be self-referential.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F7.%20Coordinated%20release-matched%20asset%20cohorts%2FTwo-commit%20construction%20and%20one%20publication%20transaction",
          "start_line": 552
        }
      ],
      "key": "two_commit_publication",
      "label": "Two-commit construction and atomic publication"
    },
    {
      "conditions": [],
      "definition": "Human Product authority's acceptance of the exact immutable RC identity, subject to mandatory qualification, review, scope, asset and gap gates. It is distinct from publication, selector movement, consumer adoption and operation outcomes.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 638,
          "quote": "- the human Product authority accepted the exact immutable RC identity.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F8.%20Acceptance%2FAcceptance%20criteria",
          "start_line": 638
        }
      ],
      "key": "rc_acceptance",
      "label": "RC acceptance"
    },
    {
      "conditions": [],
      "definition": "External backend, transport or operator-facing service outside the local carrier on which a release claim depends. It may remain outside Product for carrier and migration classification while still blocking the dependent claim.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 658,
          "quote": "Such a dependency may remain out of\nProduct for carrier and migration classification while still blocking the\ndependent release claim",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F8.%20Acceptance%2FExternal%20qualification%20dependencies",
          "start_line": 655
        }
      ],
      "key": "external_qualification_dependency",
      "label": "External qualification dependency"
    },
    {
      "conditions": [],
      "definition": "A successor's claim about one affecting predecessor claim: conserved means retained; superseded means replaced by an accepted successor relation; intentionally removed means removed by current Product authority; not applicable means no successor effect with a bounded reason. These predicates are not result values. An unresolved disposition states no claim and has no result; evaluation of a stated disposition records a separate core result with its predicate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 678,
          "quote": "- conserved: the successor retains the claim;\n- superseded: an accepted successor relation replaces it;\n- intentionally removed: current Product authority removes it; or\n- not applicable: it has no successor effect, with a bounded reason.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F9.%20Successor%20baseline%20conservation%20%28STDO-UP-015%29",
          "start_line": 675
        },
        {
          "end_line": 716,
          "quote": "An unresolved disposition states no claim and so has no result: in the\nqualification of the affected claim it is a planned assessment without a\nclosed result",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F9.%20Successor%20baseline%20conservation%20%28STDO-UP-015%29",
          "start_line": 714
        }
      ],
      "key": "successor_claim_disposition",
      "label": "Successor claim disposition"
    },
    {
      "conditions": [],
      "definition": "Provenance ledger recording this member's claimed treatment of rc.2 RELEASE_METHOD.md rows, their loci, generalisations and additions. Routes are provenance only; conserved rows are said to be restated in this member's own text. The ledger itself does not decide conservation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 746,
          "quote": "Every conserved row is restated in this member's own\ntext; a route is provenance only.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/RELEASE.md#RELEASE%2F11.%20Source%20dispositions",
          "start_line": 745
        }
      ],
      "key": "release_source_dispositions",
      "label": "Release source disposition ledger"
    },
    {
      "conditions": [],
      "definition": "Tier 2 particular method and process constitution owning method position and identity, constitutional chain and surfaces, manifesto and litmus tests, requirements and design law, trace closure, live-surface law, outcome conservation, change management, triage, classification, consistency and sprint boundaries, ambiguity, lifecycle sufficiency, lineage and release-version boundary, migration, procedures, design-record conventions and general build-tenant binding. Its mechanisms realise foundational principles and may be realised differently under those same principles.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 16,
          "quote": "nothing here is foundational, every clause\nnames the principle that requires it (P0 to P6, FOUNDATIONS §3), and each\nmechanism could be realised differently under the same principles.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD",
          "start_line": 14
        }
      ],
      "key": "spec_method",
      "label": "SPEC_METHOD"
    },
    {
      "conditions": [],
      "definition": "Meta-constitutional process for building spec-driven projects: relates goals, intent, product, requirements, design, code, evidence and repricing; defines sufficiency, requirement truth kinds and iterative authority flow. It should bootstrap a new project process without the former implementation; together with surviving domain specification it can reconstruct the project.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 57,
          "quote": "If a project's implementation\ndisappears, the method should still be sufficient to bootstrap a new\nspec-driven project process from scratch; the method plus the surviving domain specification\ncan reconstruct the project",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FProcess%20constitution",
          "start_line": 54
        }
      ],
      "key": "process_constitution",
      "label": "Process constitution"
    },
    {
      "conditions": [
        "Within urn:stdo:bounded-context:method-identity under the selected complete basis."
      ],
      "definition": "STDO names four areas: S Specification owned by SPEC_METHOD; T Ticketing owned by TICKETS; D Design owned by DESIGN_MODULE; O Outcome-Driven Development, whose complete identity and realisation meaning are owned by ODD.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 100,
          "quote": "S,\nSpecification, owned by this member; T, Ticketing, owned by\n[TICKETS](TICKETS.md); D, Design, owned by the design profile member\n[DESIGN_MODULE](DESIGN_MODULE.md); and O, Outcome-Driven Development, the\ncomplete area whose identity and realisation meaning are owned by its\nprofile member [ODD](ODD.md).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F1.%20Position%20and%20identity%2FMethod%20identity",
          "start_line": 95
        }
      ],
      "key": "stdo_method_identity",
      "label": "STDO method identity"
    },
    {
      "conditions": [],
      "definition": "F10 explains how specification governs realisations, using additional instance premises of owned layers, layered surfaces, several realisations and immutable releases. The source attributes recovered standing to P0; independent standing to P1, P2, P3, P4a and P6; derivation of P4b to P0 and P2 with non-reacquirable step-produced facts; and derivation of P5 to P0 and P6 with P0's open-world premise.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 163,
          "quote": "Standing of the commitments cited (FOUNDATIONS §3): P0\nrecovered; P1, P2, P3, P4a and P6 independent; P4b derived from P0 and\nP2, with P0's premise that step-produced facts are not re-acquirable; P5\nderived from P0 and P6, with P0's open-world premise.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FFoundation%20to%20law%3A%20chain%2C%20outcome%20and%20build-tenant%20binding",
          "start_line": 160
        }
      ],
      "key": "specification_governance_family",
      "label": "Chain, outcome and build-tenant binding family"
    },
    {
      "conditions": [],
      "definition": "Bounded work-wave surface naming current overriding concerns; more immediate than intent and higher-level than product definition and requirements. It keeps temporary focus out of deeper layers until intentionally repriced there.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 259,
          "quote": "The goals surface is the bounded work-wave surface: it captures the current\noverriding concerns for the next body of work, keeps temporary focus out of\ndeeper constitutional layers until it is intentionally repriced there, and\nis more immediate than intent while remaining higher-level than product\ndefinition and requirements.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 255
        }
      ],
      "key": "goals_surface",
      "label": "Goals"
    },
    {
      "conditions": [],
      "definition": "Constitutional surface defining purpose and direction, why the system exists and which directional changes are in or out of scope.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 419,
          "quote": "Intent states why the\nsystem exists and what directional change is in or out of scope;",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FSpecification%20surface%20rule",
          "start_line": 417
        }
      ],
      "key": "intent_surface",
      "label": "Intent"
    },
    {
      "conditions": [],
      "definition": "Present-tense definition of the mutable source project's current product realisation, key terms, boundaries and decomposable end-state shape. It bridges direction and obligation and routes to actual authority locations; it is neither the immutable release cut nor the installed product nor a rival truth surface.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 265,
          "quote": "It is not the immutable release cut\nand not the installed product; those are the lineage objects of FOUNDATIONS\n§2",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F2.%20The%20chain%2FConstitutional%20chain",
          "start_line": 263
        }
      ],
      "key": "product_definition_surface",
      "label": "Product Definition"
    },
    {
      "conditions": [],
      "definition": "Full constitutional WHAT: invariant truths the project must make true, including capabilities, guarantees, constraints, governance and verification obligations; not merely user-visible features.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 271,
